    { "name", "salt" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "maker" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "signer" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "tokenId" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "makerAmount" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "takerAmount" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "side" },
    { "type", "uint8" },
}, new Dictionary<string, object>() {
    { "name", "signatureType" },
    { "type", "uint8" },
}, new Dictionary<string, object>() {
    { "name", "timestamp" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "metadata" },
    { "type", "bytes32" },
}, new Dictionary<string, object>() {
    { "name", "builder" },
    { "type", "bytes32" },
