        string result = "";
        for (int i = 0; i < (addrChars?.Count ?? 0); i++)
        {
            string? ch = ((string)addrChars[i]);
            if (upperNibbles.IndexOf(((string)(hashChars != null && i < hashChars.Count ? hashChars[i] : null)), StringComparison.Ordinal) >= 0)
            {
                result = (result + ch.ToUpper());
            } else
